// Test-only instrumentation around the actual compiled Pages entry, executed in workerd.
// This module is generated by the required preceding build and is intentionally untracked.
// fallow-ignore-next-line unresolved-import
import pagesWorker from '../../dist/_worker.js/index.js';
export default {
  async fetch(request, env, context) {
    let bodyReads = 0;
    const read = request.arrayBuffer.bind(request);
    request.arrayBuffer = () => {
      bodyReads++;
      if (request.headers.has('X-Test-Unread-Body')) throw new Error('Request body was read');
      return read();
    };
    const bindingReads = new Set();
    const assets = {
      fetch: (forwarded) =>
        new Response(forwarded === request ? 'same request' : 'changed request'),
    };
    const testEnv = new Proxy(
      { ...env, ASSETS: assets },
      {
        get(target, key) {
          bindingReads.add(String(key));
          if (request.headers.has('X-Test-No-Bindings')) throw new Error('Binding was accessed');
          return target[key];
        },
      }
    );
    const response = await pagesWorker.fetch(request, testEnv, context);
    const result = new Response(response.body, response);
    result.headers.set('X-Test-Body-Reads', String(bodyReads));
    result.headers.set('X-Test-Body-Used', String(request.bodyUsed));
    result.headers.set('X-Test-Binding-Reads', String(bindingReads.size));
    result.headers.set('X-Test-Assets-Read', String(bindingReads.has('ASSETS')));
    result.headers.set('X-Test-Environment-Preserved', String(globalThis.__env__ === testEnv));
    return result;
  },
};
